import sys,pathlib;sys.path.insert(0,str(next(p for p in pathlib.Path(__file__).resolve().parents if (p/'rd_paths.py').is_file())));import rd_paths
from pathlib import Path
import json,hashlib,numpy as np
ROOT=rd_paths.ROOT;OUT=ROOT/'build/analysis/unsteady-2-3'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
    referencepath=ROOT/'rd/aero/unsteady-reference/records/unsteady-continuum-estimate-result.json';ref=json.loads(referencepath.read_text());assert ref['reference_continuum_qualified'];r=next(x for x in ref['records'] if x.get('side')=='reference');limit=np.array([complex(*z) for z in r['limit']]);unc=np.array(r['estimated_relative_uncertainty']);p=OUT/'candidate-symmetric-m128-n192.json';own=json.loads(p.read_text());finite=np.array([complex(*z) for z in own['transfer']]);difference=abs((finite-limit)/limit);combined=difference+unc;assert max(combined)<.01 and own['residual']<1e-11 and own['uncondensed_sample_residual']<1e-11
    result=dict(passed=True,scope='FW-V01 k=0.2 infinitesimal heave total lift and My comparison',candidate_to_reference_limit=difference.tolist(),reference_estimated_uncertainty=unc.tolist(),combined_relative_indicators=combined.tolist(),physical_unknowns=own['physical_unknowns'],algebraic_unknowns=own['algebraic_unknowns'],peak_GiB=own['peak_bytes']/2**30,seconds=own['seconds'],residual=own['residual'],uncondensed_sample_residual=own['uncondensed_sample_residual'],raw_candidate_original_space_allocation_met=False,uvlm_2_3_complete=False)
    result['sources']={q.relative_to(ROOT).as_posix():sha(q) for q in [Path(__file__),ROOT/'rd/aero/unsteady-reference/experiments/run_symmetric_heave_final.py',ROOT/'rd/aero/unsteady-reference/records/unsteady-symmetry-final-protocol.md',referencepath]};result['artifacts']={q.relative_to(ROOT).as_posix():sha(q) for q in [p,p.with_suffix('.npz'),ROOT/'build/analysis/symmetric-heave-final.log']};dest=ROOT/'rd/aero/unsteady-reference/records/symmetric-heave-final-result.json';assert not dest.exists();dest.write_text(json.dumps(result,indent=2),encoding='utf-8');print(json.dumps({k:v for k,v in result.items() if k not in ['sources','artifacts']},indent=2))
if __name__=='__main__':main()
